import java.util.*;import java.util.zip.*;import java.net.*;import java.nio.file.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class Inspect{
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}static ClassNode cls(ZipFile z,String n)throws Exception{ClassNode c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry(n+".class")).readAllBytes()).accept(c,0);return c;}
 public static void main(String[]a)throws Exception{try(ZipFile npc=new ZipFile(a[0]);ZipFile clan=new ZipFile(a[1])){String b="mod/cdv/tnpc/tactical/";for(String[] spec:new String[][]{{"CalmBrain","acquire","Social","acquire"},{"CalmBrain","rangedAttack","Social","blockPlayerAttack"},{"CalmBrain","control","Social","pause"},{"TeamBrain","tick","CompanionInventory","active"},{"StarterGear","tick","CompanionInventory","active"}}){ClassNode c=cls(npc,b+spec[0]);boolean found=false;for(MethodNode m:c.methods)if(m.name.equals(spec[1]))for(AbstractInsnNode i:m.instructions)if(i instanceof MethodInsnNode n&&n.owner.equals(b+spec[2])&&n.name.equals(spec[3]))found=true;ok(found,Arrays.toString(spec));}
 ClassNode entity=cls(npc,"mod/cdv/tnpc/entity/AutoGunOperator");for(String name:new String[]{"mobInteract","isAlliedTo","doHurtTarget"}){MethodNode m=entity.methods.stream().filter(v->v.name.equals(name)).findFirst().orElseThrow();int frames=0;for(AbstractInsnNode i:m.instructions)if(i instanceof FrameNode)frames++;ok(frames>0,"guard stack map frames: "+name);}
 ClassNode manager=cls(clan,"me/danialisntcool/factionfriction/data/FactionManager");ok(manager.fields.stream().anyMatch(f->f.name.equals("npcSocial17")&&(f.access&Opcodes.ACC_PUBLIC)!=0),"ledger field public across module boundary");for(String name:new String[]{"save","load"}){boolean found=false;for(MethodNode m:manager.methods)if(m.name.equals(name))for(AbstractInsnNode i:m.instructions)if(i instanceof MethodInsnNode n&&n.owner.equals("dev/zomboid/clans/Companions16")&&n.name.equals(name))found=true;ok(found,"persistent manager hook "+name);}
 }
 // Load patched native classes through a separate loader so JVM verification uses their new branch frames.
 try(URLClassLoader loader=new URLClassLoader(new URL[]{Path.of(a[0]).toUri().toURL()},Inspect.class.getClassLoader()){
 protected Class<?> loadClass(String name,boolean resolve)throws ClassNotFoundException{if(name.equals("mod.cdv.tnpc.tactical.CalmBrain")||name.startsWith("mod.cdv.tnpc.tactical.CalmBrain$")||name.equals("mod.cdv.tnpc.tactical.StarterGear")){synchronized(getClassLoadingLock(name)){Class<?> c=findLoadedClass(name);if(c==null)c=findClass(name);if(resolve)resolveClass(c);return c;}}return super.loadClass(name,resolve);}}){for(String c:new String[]{"CalmBrain","StarterGear"}){Class<?> nativeClass=Class.forName("mod.cdv.tnpc.tactical."+c,true,loader);ok(nativeClass.getDeclaredMethods().length>0,"native JVM verified class "+c);}}
 System.out.println("NPC_NATIVE_HOOK_AND_JVM_CHECKS="+checks);
 }
}
